// Version-drift guard.
//
// src/version.ts is GENERATED by scripts/gen-version.ts, and that generator
// only runs as the first step of `npm run build`. A merge that bumps
// package.json#version without a following build therefore leaves the
// checked-in VERSION constant stale — commit 0dcda1c exists solely to resync
// it after exactly that happened, and nothing in `npm test` caught it.
//
// This test reads the REAL files from the repo root (not a hardcoded
// version) and fails if the generated file has drifted from its input.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const REPO_ROOT = fileURLToPath(new URL('../', import.meta.url));

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error(`version-consistency: ${msg}`);
}

/** The exact provenance header scripts/gen-version.ts emits before the VERSION line. */
const GEN_HEADER =
  '// AUTO-GENERATED by scripts/gen-version.ts from package.json — do not edit by hand.\n' +
  '// Regenerated on every `npm run build`; checked in so source imports work without a build step.\n';

export const VERSION_CONSISTENCY_CASE_COUNT = 2;

export function runVersionConsistencyTests(): void {
  const pkg = JSON.parse(readFileSync(join(REPO_ROOT, 'package.json'), 'utf8')) as {
    version: string;
  };
  const versionTs = readFileSync(join(REPO_ROOT, 'src/version.ts'), 'utf8');

  // The checked-in VERSION literal must equal package.json#version.
  const match = versionTs.match(/export const VERSION: string = '([^']*)';/);
  assert(match !== null, 'src/version.ts is missing the generated `export const VERSION` line');
  const checkedIn = match[1];
  assert(
    checkedIn === pkg.version,
    `src/version.ts VERSION ('${checkedIn}') != package.json version ('${pkg.version}') — ` +
      'the generated file is stale; run `npm run build` (scripts/gen-version.ts) to regenerate it',
  );

  // And the file must be exactly what gen-version.ts derives from package.json
  // (so a hand-edit, or a generator change, also trips here).
  const expected = `${GEN_HEADER}export const VERSION: string = '${pkg.version}';\n`;
  assert(
    versionTs === expected,
    `src/version.ts does not match scripts/gen-version.ts output for package.json version ` +
      `'${pkg.version}' — regenerate it with \`npm run build\``,
  );
}
